const composerStorage=()=> 'ngyn-single-composer-'+viewUser;
let singleDraft=null,composerNetwork='Shared',previewNetwork='All';
function readSingleDraft(){try{return JSON.parse(localStorage.getItem(composerStorage()))||null}catch{return null}}
function saveSingleDraft(){try{localStorage.setItem(composerStorage(),JSON.stringify(singleDraft))}catch{toast('Browser storage is full. Try a smaller image.')}}
function initializeSingleDraft(){singleDraft=readSingleDraft()||{title:'',text:'',comment:'',channels:[],customize:false,variants:{},photo:2,mediaUrl:null,alt:'Wooden walkway through a forest of autumn trees.',assetGroup:'',guideline:'',schedule:'',format:'Feed'};singleDraft.channels=singleDraft.channels.filter(id=>assetsData.channels.some(c=>c.id===id)&&accountAllowed(id))}
function selectedComposerChannels(){return assetsData.channels.filter(c=>singleDraft.channels.includes(c.id)&&(isAdmin()||hasAccountFunction(currentUser(),'content.create','channels',c.id)))}
function composerNetworks(){return [...new Set(selectedComposerChannels().map(c=>c.network))]}
function variantFor(network){return singleDraft.customize?(singleDraft.variants[network]||(singleDraft.variants[network]={text:singleDraft.text,comment:singleDraft.comment,format:'Feed'})):singleDraft}
const pageBeforeComposer=pageAllowed;pageAllowed=function(page){if(page==='composer')return can('content.create');return pageBeforeComposer(page)};
const renderBeforeComposer=renderWorkspace;renderWorkspace=function(page=currentPage){if(page==='composer'){renderBeforeComposer('content');currentPage='composer';document.querySelector('.crumb strong').textContent='Create single post';renderSingleComposer()}else renderBeforeComposer(page)};
newPost=function(){if(!can('content.create'))return;initializeSingleDraft();composerNetwork='Shared';previewNetwork='All';renderWorkspace('composer')};
function renderSingleComposer(){if(!singleDraft)initializeSingleDraft();const channels=selectedComposerChannels(),networks=composerNetworks();if(singleDraft.customize&&!networks.includes(composerNetwork))composerNetwork=networks[0]||'Shared';const selectedVariant=singleDraft.customize&&composerNetwork!=='Shared'?variantFor(composerNetwork):singleDraft;const board=singleDraft.assetGroup?ops.boards[singleDraft.assetGroup]:null;document.querySelector('#main').innerHTML=`<div class="single-composer-header"><button class="btn" id="back-to-content">← All content</button><div><h2>New social post</h2><p>One post. Shared content or tailored network variations.</p></div><span class="badge warn">Demo composer</span></div><div class="single-composer-layout"><section class="composer-edit-panel"><div class="card"><div class="composer-destination"><div><label class="composer-label">Post to · ${channels.length} channels</label><button class="btn destination-button" id="choose-post-destinations">${channels.slice(0,4).map(c=>channelAvatar(c)).join('')}<span>${channels.length?channels.length+' selected':'Choose channels'}</span>⌄</button></div><label class="customize-switch"><input id="customize-networks" type="checkbox" role="switch" ${singleDraft.customize?'checked':''}><span>Customize for each channel</span></label></div>${singleDraft.customize?`<div class="composer-network-tabs">${networks.map(n=>`<button class="${n===composerNetwork?'active':''}" data-compose-network="${n}">${n}</button>`).join('')||'<span>Select channels first.</span>'}</div><p class="ops-muted">Editing ${safe(composerNetwork)} only. Accounts on the same network share this variation.</p>`:'<p class="ops-muted">The same caption and follow-up comment apply to all selected channels.</p>'}<div class="field"><label for="single-post-title">Internal title</label><input id="single-post-title" value="${safe(singleDraft.title)}" placeholder="For your team’s calendar"></div><div class="field"><div class="caption-label-row"><label for="single-post-text">${singleDraft.customize?safe(composerNetwork)+' caption':'Post content'}</label><span id="single-char-count">${selectedVariant.text.length} characters · API limits unverified</span></div><textarea id="single-post-text" rows="7" placeholder="Write your post here…">${safe(selectedVariant.text)}</textarea></div><div class="composer-tools"><button class="btn" id="single-ai-draft">✦ Mock AI draft</button><button class="btn" id="insert-emoji" aria-label="Insert leaf emoji">☺ Emoji</button><button class="btn" id="insert-hashtag"># Hashtag</button><button class="btn" id="insert-link">↗ Link</button></div><div class="field"><label for="single-followup">Follow-up comment · ${singleDraft.customize?safe(composerNetwork):'shared'}</label><textarea id="single-followup" rows="3" placeholder="Optional first comment…">${safe(selectedVariant.comment)}</textarea><small>Saved for the mock workflow. Platform support is unverified; no comment is sent.</small></div><details class="composer-advanced"><summary>Advanced options</summary><div class="field"><label for="single-post-format">${singleDraft.customize?safe(composerNetwork):'Shared'} format · demo only</label><select id="single-post-format">${['Feed','Reel','Story'].map(f=>`<option ${selectedVariant.format===f?'selected':''}>${f}</option>`)}</select><small>These are planning labels. Native format availability and video requirements must be verified.</small></div><div class="field"><label for="single-schedule">Requested schedule · America/Halifax</label><input id="single-schedule" type="datetime-local" value="${singleDraft.schedule}"><small>Submitting requests review. Scheduling still requires approval and publishing permission.</small></div></details></div><div class="card"><h3>Media & accessibility</h3><div class="composer-photo-choices">${samplePhotos.map((p,i)=>`<button type="button" data-single-photo="${i}" class="${!singleDraft.mediaUrl&&singleDraft.photo===i?'selected':''}" aria-label="Use ${safe(p.alt)}"><img src="${samplePhoto(i,220)}" alt="${safe(p.alt)}" loading="lazy" referrerpolicy="no-referrer"></button>`).join('')}</div><div class="field" style="margin-top:20px"><label for="single-media-file">Upload photo · PNG, JPEG or WebP, max 600 KB</label><input id="single-media-file" type="file" accept="image/png,image/jpeg,image/webp"><small>Stored locally. Video uploading is not implemented in this demo.</small></div><div class="field"><label for="single-alt">ALT text</label><input id="single-alt" value="${safe(singleDraft.alt)}" required></div></div><div class="card"><h3>Brand context</h3><div class="field"><label for="single-brand-group">Asset group</label><select id="single-brand-group"><option value="">No brand context selected</option>${assetsData.groups.filter(g=>isAdmin()||assetsData.channels.some(c=>c.assetGroup===g.id&&accountAllowed(c.id))).map(g=>`<option value="${g.id}" ${g.id===singleDraft.assetGroup?'selected':''}>${safe(g.name)}</option>`).join('')}</select></div><div class="field"><label for="single-guideline">Guideline set · guide + visuals</label><select id="single-guideline"><option value="">Choose a guideline</option>${(board?.sets||[]).map(s=>`<option value="${s.id}" ${s.id===singleDraft.guideline?'selected':''}>${safe(s.name)}${s.reviewed?'':' · needs review'}</option>`).join('')}</select></div><p class="ops-muted">Master rules and selected guidance inform mock drafts. Human editorial review is still required. Selecting a brand never grants channel access.</p></div></section><aside class="composer-preview-panel"><div class="preview-heading"><h3>Post preview</h3><span class="badge">Approximate layouts</span></div><div class="composer-preview-tabs"><button data-preview-net="All" class="${previewNetwork==='All'?'active':''}">All</button>${networks.map(n=>`<button data-preview-net="${n}" class="${previewNetwork===n?'active':''}">${n}</button>`).join('')}</div><div id="single-post-previews"></div></aside></div><div class="single-composer-footer"><span id="single-draft-status">Draft kept in this browser. Nothing is sent externally.</span><div class="actions"><button class="btn" id="single-save-draft">Save draft</button><button class="btn primary" id="single-submit-review">Submit for approval</button></div></div>`;document.querySelector('#back-to-content').onclick=()=>{saveSingleDraft();renderWorkspace('content')};document.querySelector('#choose-post-destinations').onclick=chooseComposerChannels;document.querySelector('#customize-networks').onchange=e=>{singleDraft.customize=e.target.checked;if(singleDraft.customize)networks.forEach(n=>variantFor(n));composerNetwork=networks[0]||'Shared';saveSingleDraft();renderSingleComposer()};document.querySelectorAll('[data-compose-network]').forEach(b=>b.onclick=()=>{composerNetwork=b.dataset.composeNetwork;renderSingleComposer()});document.querySelector('#single-post-title').oninput=e=>{singleDraft.title=e.target.value;saveSingleDraft()};document.querySelector('#single-post-text').oninput=e=>{selectedVariant.text=e.target.value;document.querySelector('#single-char-count').textContent=e.target.value.length+' characters · API limits unverified';saveSingleDraft();renderSinglePreviews()};document.querySelector('#single-followup').oninput=e=>{selectedVariant.comment=e.target.value;saveSingleDraft();renderSinglePreviews()};document.querySelector('#single-post-format').onchange=e=>{selectedVariant.format=e.target.value;saveSingleDraft();renderSinglePreviews()};document.querySelector('#single-schedule').onchange=e=>{singleDraft.schedule=e.target.value;saveSingleDraft()};document.querySelector('#single-alt').oninput=e=>{singleDraft.alt=e.target.value;saveSingleDraft();renderSinglePreviews()};document.querySelectorAll('[data-single-photo]').forEach(b=>b.onclick=()=>{singleDraft.photo=Number(b.dataset.singlePhoto);singleDraft.mediaUrl=null;singleDraft.alt=samplePhotos[singleDraft.photo].alt;saveSingleDraft();renderSingleComposer()});document.querySelector('#single-media-file').onchange=e=>{const f=e.target.files[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>600*1024){toast('Use PNG, JPEG or WebP under 600 KB.');return}const r=new FileReader();r.onload=()=>{singleDraft.mediaUrl=r.result;singleDraft.alt='';saveSingleDraft();renderSingleComposer();toast('Local photo added. Add an ALT description.')};r.readAsDataURL(f)};document.querySelector('#single-brand-group').onchange=e=>{singleDraft.assetGroup=e.target.value;singleDraft.guideline='';if(singleDraft.assetGroup){const previous=assetsData.selected;assetsData.selected=singleDraft.assetGroup;ensureBrandPackage();assetsData.selected=previous}saveSingleDraft();renderSingleComposer()};document.querySelector('#single-guideline').onchange=e=>{singleDraft.guideline=e.target.value;saveSingleDraft()};document.querySelectorAll('[data-preview-net]').forEach(b=>b.onclick=()=>{previewNetwork=b.dataset.previewNet;renderSingleComposer()});document.querySelector('#single-save-draft').onclick=()=>saveComposerPosts('Draft');document.querySelector('#single-submit-review').onclick=()=>saveComposerPosts('In review');document.querySelector('#single-ai-draft').onclick=()=>{const brand=ops.boards[singleDraft.assetGroup],set=brand?.sets.find(s=>s.id===singleDraft.guideline);if(singleDraft.guideline&&(!set?.reviewed||!validGuidelinePackage(set))){toast('Review the complete guideline package before using it for a mock draft.');return}selectedVariant.text='[MOCK DRAFT — verify facts] '+(singleDraft.title||'Your municipal update')+'. Here is what residents need to know: [approved service facts], [effective date], and [verified next steps].'+(set?' Draft direction: '+set.name+'.':'');saveSingleDraft();renderSingleComposer();toast('Mock draft inserted. No AI service called.')};document.querySelector('#insert-emoji').onclick=()=>insertComposerText(' 🍃');document.querySelector('#insert-hashtag').onclick=()=>insertComposerText(' #Harbourview');document.querySelector('#insert-link').onclick=()=>insertComposerText(' https://harbourview.example/services');renderSinglePreviews()}
function insertComposerText(value){const field=document.querySelector('#single-post-text'),start=field.selectionStart,end=field.selectionEnd;field.setRangeText(value,start,end,'end');field.dispatchEvent(new Event('input',{bubbles:true}));field.focus()}
function chooseComposerChannels(){const available=assetsData.channels.filter(c=>isAdmin()||hasAccountFunction(currentUser(),'content.create','channels',c.id));assetModal('Post to channels',`<form id="composer-channels-form"><p class="form-description">Choose independently connected accounts you can access. Expired channels can receive drafts but cannot be processed in the demo queue.</p><div class="resource-list">${available.map(c=>`<label class="resource-option"><input name="composer-destination" type="checkbox" value="${c.id}" ${singleDraft.channels.includes(c.id)?'checked':''}>${channelAvatar(c)}<span><strong>${safe(c.name)}</strong><small>${c.network} · ${connectionState(c)}</small></span></label>`).join('')||'<p>No assigned channels. Ask an administrator for access.</p>'}</div><div class="form-actions"><button type="button" class="btn" data-close>Cancel</button><button type="submit" class="btn primary">Apply channels</button></div></form>`);document.querySelector('#composer-channels-form').onsubmit=e=>{e.preventDefault();singleDraft.channels=[...document.querySelectorAll('[name="composer-destination"]:checked')].map(c=>c.value);saveSingleDraft();close();renderSingleComposer()}}
function renderSinglePreviews(){const channels=selectedComposerChannels().filter(c=>previewNetwork==='All'||c.network===previewNetwork);document.querySelector('#single-post-previews').innerHTML=channels.map(c=>{const v=variantFor(c.network),p={channel:c.id,title:singleDraft.title||'Untitled draft',text:v.text||'Your post content will appear here.',art:singleDraft.photo,alt:singleDraft.alt,mediaUrl:singleDraft.mediaUrl,mediaAssetId:singleDraft.mediaAssetId};return `<section style="margin-bottom:22px"><div class="composer-preview-label"><span>${c.network} · ${safe(v.format||'Feed')}</span><span class="badge ${connectionState(c)==='Expired'?'fail':'warn'}">${connectionState(c)} · demo</span></div>${postMarkup(p)}${v.comment?`<div class="composer-followup-preview"><strong>Follow-up comment · demo</strong><p>${safe(v.comment)}</p></div>`:''}</section>`}).join('')||'<div class="ops-empty"><h3>Select channels to preview</h3><p>Your caption, media and network variations update here as you edit.</p></div>'}
function saveComposerPosts(status){if(!can('content.create'))return;const channels=selectedComposerChannels();if(!channels.length){toast('Select at least one assigned channel.');return}if(!singleDraft.title.trim()||!singleDraft.alt.trim()||channels.some(c=>!variantFor(c.network).text.trim())){toast('Add an internal title, caption for every selected network and ALT text.');return}const group=ops.boards[singleDraft.assetGroup],set=group?.sets.find(s=>s.id===singleDraft.guideline);if(singleDraft.guideline&&(!set?.reviewed||!validGuidelinePackage(set))){toast('Review the complete guideline package before submitting.');return}if(singleDraft.assetGroup&&channels.some(c=>c.assetGroup!==singleDraft.assetGroup)){toast('Selected channels must belong to the chosen brand Asset Group, or clear the brand context.');return}const batchId=singleDraft.batchId||crypto.randomUUID();singleDraft.batchId=batchId;channels.forEach(c=>{const v=variantFor(c.network),old=ops.posts.find(p=>p.batchId===batchId&&p.channel===c.id);const data={id:old?.id||'POST-'+crypto.randomUUID(),batchId,channel:c.id,title:singleDraft.title.trim(),text:v.text.trim(),comment:v.comment,format:v.format||'Feed',art:singleDraft.photo,mediaUrl:singleDraft.mediaUrl,mediaAssetId:singleDraft.mediaAssetId,mediaCredit:singleDraft.mediaCredit,alt:singleDraft.alt.trim(),status,scheduled:singleDraft.schedule,created:old?.created||nowISO(),history:[...(old?.history||[]),{action:status==='Draft'?'Single-post draft saved':'Single-post variation submitted',time:nowISO()}],brandContext:singleDraft.assetGroup,guidelineId:singleDraft.guideline};if(old&&['Draft','Failed'].includes(old.status))Object.assign(old,data);else if(!old)ops.posts.unshift(data)});logOps(status==='Draft'?'Single post saved':'Single post submitted for human approval',batchId+'; '+channels.length+' channel variations.');saveSingleDraft();if(status==='In review'){localStorage.removeItem(composerStorage());singleDraft=null;renderWorkspace('content')}else document.querySelector('#single-draft-status').textContent='Saved '+channels.length+' draft variations in this browser.';toast(status==='Draft'?'Draft saved.':'Submitted for approval. No external publishing.')}
const postBeforeLocalMedia=postMarkup;postMarkup=function(p){let result=postBeforeLocalMedia(p);result=result.replaceAll('alt="'+safe(samplePhotos[(p.art||0)%samplePhotos.length].alt)+'"','alt="'+safe(p.alt||samplePhotos[(p.art||0)%samplePhotos.length].alt)+'"');if(p.mediaUrl){result=result.replaceAll(samplePhoto(p.art),p.mediaUrl);result=result.replace(/<span class="photo-credit">[\s\S]*?<\/span>/,'<span class="photo-credit">User-selected local demo image. No external upload.</span>')}return result};
const queueBeforeExpiry=processQueue;processQueue=function(){if(can('content.publish')&&!ops.paused){const p=visiblePosts().find(p=>p.status==='Scheduled'&&(isAdmin()||hasAccountFunction(currentUser(),'content.publish','channels',p.channel)));if(p&&connectionState(channelById(p.channel))==='Expired'){p.status='Failed';p.history.push({action:'Simulated token expired; no transmission',time:nowISO()});logOps('Demo job blocked by expired connection',p.id);renderWorkspace(currentPage);toast('Demo job failed: channel token expired. Reauthorize separately.');return}}queueBeforeExpiry()};
